render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(from = cfg$x, to = cfg$y, value = cfg$group), c("from", "to", "value")); from_values <- as.character(data[[cfg$x]]); to_values <- as.character(data[[cfg$y]]); value_values <- data[[cfg$group]]; nodes <- sort(unique(c(from_values, to_values))); mat <- matrix(0, nrow = length(nodes), ncol = length(nodes), dimnames = list(nodes, nodes)); for (i in seq_len(nrow(data))) mat[from_values[i], to_values[i]] <- value_values[i]; chart_open_device(cfg$outputPath, cfg$format); circlize::circos.clear(); circlize::chordDiagram(mat, transparency = 35, annotationTrack = "grid"); title(cfg$title %||% "群组关系弦图"); circlize::circos.clear(); grDevices::dev.off(); cfg$outputPath }
